from solution import sum_digits_twoparts


def test_issue_example_35():
    """Example: sum_digits_twoparts(35)==17."""
    assert sum_digits_twoparts(35) == 17  # 2+9+6=17 from 29+6=35


def test_issue_zero():
    """Maximum digit-sum split of 0 is 0."""
    assert sum_digits_twoparts(0) == 0  # 0+0=0 from 0+0=0


def test_issue_single_digit():
    """Maximum digit-sum split of 7 is 7."""
    assert sum_digits_twoparts(7) == 7  # 3+4=7 from 3+4=7


def test_issue_ten():
    """Maximum digit-sum split of 10 is 10."""
    assert sum_digits_twoparts(10) == 10  # 1+9=10 from 1+9=10


def test_issue_eighteen():
    """Maximum digit-sum split of 18 is 18."""
    assert sum_digits_twoparts(18) == 18  # 9+9=18 from 9+9=18


def test_issue_nineteen():
    """Maximum digit-sum split of 19 is 10."""
    assert sum_digits_twoparts(19) == 10  # 9+1=10 from 9+10=19


def test_issue_twenty():
    """Maximum digit-sum split of 20 is 11."""
    assert sum_digits_twoparts(20) == 11  # 1+1+9=11 from 11+9=20


def test_issue_ninety_nine():
    """Maximum digit-sum split of 99 is 18."""
    assert sum_digits_twoparts(99) == 18  # 9+9=18 from 9+90=99


def test_issue_hundred():
    """Maximum digit-sum split of 100 is 19."""
    assert sum_digits_twoparts(100) == 19  # 4+9+5+1=19 from 49+51=100


def test_issue_thousand():
    """Maximum digit-sum split of 1000 is 28."""
    assert sum_digits_twoparts(1000) == 28  # 4+9+9+5+0+1=28 from 499+501=1000


def test_contract_modulo_congruence():
    """Maximum digit sum must be congruent to N mod 9."""
    assert sum_digits_twoparts(100) % 9 == 1  # 100%9=1 and 19%9=1, 18+1=19


def test_contract_lower_bound_trivial_split():
    """Maximum digit sum is at least digit sum of N itself."""
    assert sum_digits_twoparts(35) >= 8  # 3+5=8 from 35+0=35
